Item.method_code:
/*
否認時の実行処理のまとめ
*/

using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{
    Innovator inn = this.getInnovator();
    string type = this.getType();
    string id = this.getID();
    
    //　ダイレクトの時のみ（WF使用時は、WFでキックする）
    if(this.getProperty("h4_approve_style","") == "0")
    {
        // やるやら×の必要資料の承認者と承認日時を入力する
        Item callMethod = inn.newItem("method","h4_MQPReject_SetReqDocRejecter");
        callMethod.setProperty("type", type);
        callMethod.setProperty("id", id);
        callMethod = callMethod.apply();
        if(callMethod.isError())
        {
            return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
        }
    }

    return this;
}
